  sala       text NOT NULL REFERENCES salas (codigo),
  vigencia   daterange NOT NULL,
  valor_hora integer NOT NULL CHECK (valor_hora > 0),
  PRIMARY KEY (sala, vigencia WITHOUT OVERLAPS)
);
CREATE TABLE arriendos (
  id      integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  sala    text NOT NULL,
  periodo daterange NOT NULL,
  FOREIGN KEY (sala, PERIOD periodo) REFERENCES tarifas (sala, PERIOD vigencia)
);
